import{c as e,J as a,h as o,k as n}from"./chunks/framework.WgZQdPFo.js";const u=JSON.parse('{"title":"Capital Overview & Philosophy","description":"Unified personal finance contour for master craftsmen, separating workshop cash from personal funds, and automated expense tracking via balance delta.","frontmatter":{"title":"Capital Overview & Philosophy","description":"Unified personal finance contour for master craftsmen, separating workshop cash from personal funds, and automated expense tracking via balance delta.","order":16},"headers":[],"relativePath":"docs/spaces/moy-kapital/overview.md","filePath":"docs/spaces/moy-kapital/overview.md","lastUpdated":1794012535000}'),s={name:"docs/spaces/moy-kapital/overview.md"};function r(i,t,l,c,d,p){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="capital-overview-philosophy" tabindex="-1">Capital Overview &amp; Philosophy <a class="header-anchor" href="#capital-overview-philosophy" aria-label="Permalink to &quot;Capital Overview &amp; Philosophy&quot;">​</a></h1><p>Every craft workshop owner and maker eventually faces the same fundamental dilemma: where does the workshop&#39;s money end and personal family finances begin?</p><p>Mixing leather or wood purchases, workshop rent, and personal grocery bills in a single bank account destroys financial visibility. It becomes impossible to tell whether the business generates genuine net profit or merely stays afloat through continuous personal subsidies.</p><p>The <strong>My Capital</strong> workspace in OmniCraft ERP PRO mode resolves this challenge by establishing a strict, automated boundary between business operations and personal wealth—without forcing you to become an exhausted bookkeeper collecting supermarket receipts.</p><hr><h2 id="two-contour-principle-workshop-cash-vs-maker-s-pocket" tabindex="-1">Two-Contour Principle: Workshop Cash vs. Maker&#39;s Pocket <a class="header-anchor" href="#two-contour-principle-workshop-cash-vs-maker-s-pocket" aria-label="Permalink to &quot;Two-Contour Principle: Workshop Cash vs. Maker&#39;s Pocket&quot;">​</a></h2><p>The financial architecture of OmniCraft ERP separates money flows into two distinct contours:</p><ol><li><strong>Workshop Operational Contour (Production Workspaces):</strong> raw materials inventory, cost calculation, work in progress on the workbench, cash flow ledger (DDS), and finished goods showcase.</li><li><strong>Consolidated Capital Contour (My Capital Workspace):</strong> the total net worth of the owner, including personal bank accounts, savings, investment portfolios, equipment, real estate, and equity in each production workspace.</li></ol><div class="info custom-block"><p class="custom-block-title">Database Isolation</p><p>Personal finances are stored in a dedicated, isolated database file <code>personal_finance.db</code>. Your personal bank accounts, investments, and private assets never leak into production reports and remain strictly confidential.</p></div><hr><h2 id="mathematical-delta-automated-expenses-without-receipt-tracking" tabindex="-1">Mathematical Delta: Automated Expenses Without Receipt Tracking <a class="header-anchor" href="#mathematical-delta-automated-expenses-without-receipt-tracking" aria-label="Permalink to &quot;Mathematical Delta: Automated Expenses Without Receipt Tracking&quot;">​</a></h2><p>The core engineering breakthrough of My Capital is the <strong>Balance Delta expense calculation method</strong>.</p><p>Most personal finance apps demand robotic discipline: entering every coffee, fuel, and meal expense manually every single day. In reality, craftsmen abandon this routine within two weeks.</p><p>OmniCraft ERP applies an inverted engineering approach:</p><p>$$\\text{Personal Expenses} = \\text{Initial Capital} + \\text{Workshop Profit &amp; Personal Income} - \\text{Ending Capital}$$</p><p>You simply update account balances once a week or at month-end. The program automatically balances the delta against workshop operations and calculates the exact amount spent on personal life.</p><div class="tip custom-block"><p class="custom-block-title">Peace of Mind</p><p>If personal bank balances increase over the month while workshop net profit is confirmed by finished goods sales, your business is genuinely thriving. If balances deplete, the system highlights the unallocated outflow before a cash flow crisis occurs.</p></div><hr><h2 id="architecture-of-my-capital" tabindex="-1">Architecture of My Capital <a class="header-anchor" href="#architecture-of-my-capital" aria-label="Permalink to &quot;Architecture of My Capital&quot;">​</a></h2><p>The workspace interface is structured into a streamlined 5-step funnel:</p><ul><li><strong>Accounts &amp; Investments:</strong> central hub for liquid funds. Houses two sub-tabs: &quot;Accounts &amp; Wallets&quot; (cash, cards, deposits, multi-currency, and stablecoins) and &quot;Investment Portfolio&quot; (stocks, bonds, loans, business equity).</li><li><strong>Property &amp; Resources:</strong> long-term physical assets outside production (specialized machinery, vehicles, workshop premises).</li><li><strong>Personal Operations:</strong> ledger of significant personal income and major capital expenditures.</li><li><strong>Capital Dashboard:</strong> Net Worth command center combining personal holdings and production capital across all connected workspaces.</li><li><strong>Capital Analytics:</strong> long-term wealth growth charts, currency basket distribution, and asset class balancing.</li></ul><hr><h2 id="two-level-navigation-and-contextual-action-bars" tabindex="-1">Two-Level Navigation and Contextual Action Bars <a class="header-anchor" href="#two-level-navigation-and-contextual-action-bars" aria-label="Permalink to &quot;Two-Level Navigation and Contextual Action Bars&quot;">​</a></h2><p>The space interface follows a canonical two-level information architecture designed for high information density and zero visual waste:</p><ul><li><strong>Level 1 (Space Navigation Bar):</strong> Located at the very top of the window, exclusively dedicated to clean switching between the five domains (&quot;Accounts &amp; Investments&quot;, &quot;Property &amp; Resources&quot;, &quot;Personal Operations&quot;, &quot;Capital Dashboard&quot;, &quot;Capital Analytics&quot;). The top bar remains free of orphaned action buttons.</li><li><strong>Level 2 (Contextual Action Bars per Screen):</strong> Utility tools are co-located directly within the screens where they are needed:</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Screen</th><th style="text-align:left;">Location</th><th style="text-align:left;">Action Tools</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Accounts &amp; Investments</strong></td><td style="text-align:left;">Opposite &quot;Accounts / Investments&quot; tabs</td><td style="text-align:left;"><strong>📊 Statistics</strong>, <strong>💱 Rates</strong>, <strong>⚙️ Settings</strong>, <strong>📖 Docs</strong></td><td style="text-align:left;">Currency basket breakdown, rate updates, account/investment categories, and liquid capital documentation.</td></tr><tr><td style="text-align:left;"><strong>Property &amp; Resources</strong></td><td style="text-align:left;">Opposite asset category filter capsules</td><td style="text-align:left;"><strong>🛡️ Duplicates</strong>, <strong>+ Add Asset</strong>, <strong>📖 Docs</strong></td><td style="text-align:left;">Ownership share collision audit (Hamilton method), asset cataloging, and material registry reference.</td></tr><tr><td style="text-align:left;"><strong>Personal Operations</strong></td><td style="text-align:left;">In the operations table header</td><td style="text-align:left;"><strong>📖 Docs</strong></td><td style="text-align:left;">Guidelines for recording personal revenue streams and significant capital expenditures.</td></tr><tr><td style="text-align:left;"><strong>Capital Dashboard</strong></td><td style="text-align:left;">In the consolidated dashboard header</td><td style="text-align:left;"><strong>🔄 Refresh</strong>, <strong>📖 Docs</strong></td><td style="text-align:left;">Instant net worth recalculation and consolidated wealth structure inspection.</td></tr><tr><td style="text-align:left;"><strong>Capital Analytics</strong></td><td style="text-align:left;">In the trend dynamics header</td><td style="text-align:left;"><strong>🚀 Roadmap</strong>, <strong>📖 Docs</strong></td><td style="text-align:left;">Wealth trajectory analytics and historical continuity inspection across closed workspaces.</td></tr></tbody></table><hr><h2 id="privacy-zero-api-dependency" tabindex="-1">Privacy &amp; Zero-API Dependency <a class="header-anchor" href="#privacy-zero-api-dependency" aria-label="Permalink to &quot;Privacy &amp; Zero-API Dependency&quot;">​</a></h2><p>All financial calculations happen <strong>strictly offline on your local computer</strong>. OmniCraft ERP never transmits your balances, investments, or bank credentials to third-party clouds or tracking servers. Currency rates update in a single click without recurring API fees: the system queries resilient open rate gateways (European Central Bank, Central Bank of Russia, CoinGecko) for fiat and cryptocurrencies, while also allowing instant manual edits or external AI prompt exports.</p>',29)])])}const g=e(s,[["render",r]]);export{u as __pageData,g as default};
